import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"handl Formatter","description":"","frontmatter":{"title":"handl Formatter","type":"adr","date":"2026-08-24T00:00:00.000Z","status":"proposed","status_note":"Proposed"},"headers":[],"relativePath":"handl/project/adrs/0014-formatter.md","filePath":"vendored/handl/project/adrs/0014-formatter.md"}`),a={name:`handl/project/adrs/0014-formatter.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-formatter" tabindex="-1">handl Formatter <a class="header-anchor" href="#handl-formatter" aria-label="Permalink to “handl Formatter”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>handl documents can be written in multiple frontends (YAML, JSON, TOML, <code>.handl</code>). Within each frontend, the same logical document can be formatted in many different styles: extra blank lines, mixed indentation, keys in arbitrary order, trailing whitespace. This creates noisy diffs, harder reviews, and formatting arguments in pull requests.</p><p>A language-aware formatter — like <code>gofmt</code>, <code>rustfmt</code>, or <code>prettier</code> — enforces a canonical style. Unlike generic formatters, an handl formatter understands the document model: field declarations, schemas, expressions, imports, annotations. It can enforce canonical key order that matches the language semantics, not just alphabetical or insertion order.</p><p>The previous design (a handl-hosted <code>handl fmt</code> command with per-frontend parse/stringify pipelines and two placeholder plugin crates, <code>plugin-fmt-expression</code> and <code>plugin-fmt-stmt</code>) was never implemented beyond stubs. Those crates have been removed. This ADR replaces that design with a formatter built <strong>in handl, for handl</strong> — a generic, extensible, modular formatter with plugin support.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>The formatter is a <strong>tool written in handl itself</strong>, not a host-level Rust command. It is generic (parameterized by <code>Language</code>, per ADR-0041 Phase 1: &quot;one formatter formats any language you have a value for&quot;), extensible via plugins, and modular (formatting rules are contributed by separate plugins rather than monolithic).</p><h3 id="generic-core-pluggable-rules" tabindex="-1">Generic core, pluggable rules <a class="header-anchor" href="#generic-core-pluggable-rules" aria-label="Permalink to “Generic core, pluggable rules”">​</a></h3><p>The platform provides the generic formatter primitives — the <code>Format</code> operation, <code>FormatBehavior</code> trait, <code>FormatRequest</code>, and <code>BasicFormatter</code> rule acceptor in <code>handl-platform</code> (re-exported via <code>plugin-ext-fmt</code>). These are the contract; they carry no language-specific formatting logic.</p><p>Formatting rules are contributed by plugins that implement <code>FormatBehavior</code>, keyed by <code>AstNode.kind</code>. A rule for <code>if</code>-expressions, a rule for <code>import</code> statements, a rule for object literals — each is a separate, composable plugin. Hosts and kits assemble the rule set they want; the canonical kit ships the canonical handl rules.</p><h3 id="command-surface" tabindex="-1">Command surface <a class="header-anchor" href="#command-surface" aria-label="Permalink to “Command surface”">​</a></h3><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">handl</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> fmt</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> document.yaml</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;">              #</span><span style="--shiki-dark:#BBBBBB;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;"> print formatted output to stdout</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">handl</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> fmt</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> document.yaml</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --write</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;">      #</span><span style="--shiki-dark:#BBBBBB;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;"> overwrite the file in place</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">handl</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> fmt</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> document.yaml</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --check</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;">      #</span><span style="--shiki-dark:#BBBBBB;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;"> exit non-zero if not already formatted</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">handl</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> fmt</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> libraries/</span><span style="--shiki-dark:#0F0;--shiki-light:#005CC5;">**</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">/</span><span style="--shiki-dark:#0F0;--shiki-light:#005CC5;">*</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">.yaml</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --write</span><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;">  #</span><span style="--shiki-dark:#BBBBBB;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;"> format many files</span></span></code></pre></div><h3 id="canonical-style" tabindex="-1">Canonical style <a class="header-anchor" href="#canonical-style" aria-label="Permalink to “Canonical style”">​</a></h3><ol><li><strong>Two-space indentation</strong> (YAML, <code>.handl</code>). JSON and TOML follow their native conventions.</li><li><strong>A single trailing newline</strong> at the end of each file.</li><li><strong>No trailing whitespace</strong> on any line.</li><li><strong>Canonical key order for mappings.</strong> Unknown keys are kept after known keys in their original relative order. <ul><li>Document top-level: <code>annotations</code>, <code>version</code>, <code>import</code>, <code>fields</code>, <code>functions</code>, <code>data</code>.</li><li>Field mapping: <code>type</code>, <code>expr</code>, <code>arg</code>, <code>schema</code>, <code>inheritable</code>, <code>mutable</code>, <code>merge</code>.</li></ul></li><li><strong>Array order is preserved.</strong> Authors may group items intentionally.</li><li><strong>Comments are preserved</strong> where the underlying document model supports it.</li></ol><h3 id="frontend-specific-behavior" tabindex="-1">Frontend-specific behavior <a class="header-anchor" href="#frontend-specific-behavior" aria-label="Permalink to “Frontend-specific behavior”">​</a></h3><p>The formatter dispatches based on file extension:</p><table tabindex="0"><thead><tr><th>Extension</th><th>Formatter</th></tr></thead><tbody><tr><td><code>.yaml</code> / <code>.yml</code></td><td>YAML formatter (parse, reorder keys, stringify)</td></tr><tr><td><code>.json</code></td><td>JSON formatter (parse, reorder keys, pretty-print)</td></tr><tr><td><code>.toml</code></td><td>TOML formatter (parse, reorder keys, stringify)</td></tr><tr><td><code>.handl</code></td><td><code>.handl</code> formatter (parse AST, emit canonical syntax)</td></tr></tbody></table><p>Each frontend&#39;s formatter shares the same canonical key order and style rules, but implements them through its own parse/stringify pipeline, exposed as formatting plugins.</p><h3 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to “Implementation”">​</a></h3><ul><li>The formatter operates on the parsed document, re-orders mapping keys with a schema-aware sorter, then stringifies with the canonical rules.</li><li><code>--check</code> compares the emitted text to the original and exits <code>1</code> when they differ, but does not write anything.</li><li><code>--write</code> overwrites the source file atomically.</li><li>The formatter does not resolve imports or merge included files — it formats only the file being edited.</li></ul><h3 id="plugin-architecture" tabindex="-1">Plugin architecture <a class="header-anchor" href="#plugin-architecture" aria-label="Permalink to “Plugin architecture”">​</a></h3><p>The formatter is part of the handl toolchain, not a host-specific feature. The generic core (<code>BasicFormatter</code>, <code>FormatBehavior</code>) lives in <code>handl-platform</code> / <code>plugin-ext-fmt</code>. Language-specific rules are plugins: hosts and applications (e.g. Peregrin) extend the canonical key order with host-specific keys via plugin configuration, and kits curate which formatting plugins are loaded. The formatter is modular — each rule set is an independent plugin — and extensible — new languages and frontends add formatting by contributing new <code>FormatBehavior</code> plugins, not by editing a monolithic formatter.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>All handl documents can be formatted the same way, reducing style noise in diffs.</li><li><code>handl fmt --check</code> can run in CI to enforce formatting.</li><li>The formatter stays in sync with the language model, so language changes can update the canonical style by updating the relevant formatting plugin.</li><li>Existing documents need a one-time pass with <code>handl fmt --write</code>.</li><li>Each frontend needs its own parse/stringify implementation, but the key ordering logic is shared through the generic core.</li><li>The formatter is self-hosting-capable: because it is a handl tool, it can format its own source, consistent with ADR-0041&#39;s &quot;every language gets every tool, for free.&quot;</li><li>Adding a new language or frontend is a plugin contribution, not a core change.</li></ul>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};